const btn=(act,text,cls='btn',attrs='')=>`<button type="button" class="${cls}" data-action="${act}" ${attrs}>${text}</button>`;
const icobtn=(act,ic,label,attrs='',cls='')=>btn(act,icon(ic),'icon-button '+cls,`aria-label="${esc(label)}" title="${esc(label)}" ${attrs}`);
