function productCardV03(p){return `<article class="product-card" data-product-card="${esc(p.id)}"><span class="product-tag">${esc(v(catBy(p.category).name))}</span>${icobtn('favorite','heart',t('Salvează modelul','Save model'),`data-id="${esc(p.id)}" aria-pressed="${favorites.includes(p.id)}"`,'save-btn '+(favorites.includes(p.id)?'saved':''))}${a('/product/'+p.id,photo(p),'product-photo-link',`aria-label="${esc(t('Vezi ','View ')+p.name)}"`)}<div class="product-info"><span class="product-brand">${esc(p.brand)}</span><h3>${a('/product/'+p.id,esc(p.name))}</h3><p>${esc(v(p.description))}</p><div class="product-stats"><span>${esc(v(domBy(p.domains[0]).name))}</span>${p.heightCm!==null&&p.category==='umanoizi'?`<span>${esc(p.heightCm)} cm</span>`:''}${p.payloadKg!==null?`<span>${esc(p.payloadKg)} kg${['unitree-g1','rokae-helios','rokae-human-x'].includes(p.id)?t('/braț','/arm'):''}</span>`:''}</div><div class="price-line"><b>${priceText(p)}</b><small>${t('Configurație la cerere','Configuration on request')}</small></div><div class="card-actions">${a('/product/'+p.id,t('Descoperă','Explore')+' '+icon('arrow'),'btn sm')}${icobtn('add-cart','cart',t('Adaugă în selecție','Add to selection'),`data-id="${p.id}"`)}${icobtn('compare','compare',t('Compară modelul','Compare model'),`data-id="${p.id}" aria-pressed="${compare.includes(p.id)}"`,'compare-card')}</div></div></article>`;}
function sortedProducts(ps,sort='recommended'){const rank=p=>p.fallback?0:p.image&&!failed.has(p.id)?1:2;return [...ps].sort((x,y)=>rank(x)-rank(y)||(sort==='az'?x.name.localeCompare(y.name):sort==='za'?y.name.localeCompare(x.name):x.priority-y.priority));}
