function approvedSyncConnector(){
 const group=$('.ap-art-group'),img=$('#ap-hero-robot'),lens=$('.ap-lens'),svg=$('.ap-connector');
 if(!group||!img||!lens||!svg)return;
 const g=group.getBoundingClientRect(),r=img.getBoundingClientRect(),l=lens.getBoundingClientRect();
 if(!g.width||!r.width)return;
 const x=r.left-g.left+r.width*V.anklePoint[0],y=r.top-g.top+r.height*V.anklePoint[1];
 const sx=l.right-g.left-3,sy=l.top-g.top+l.height*.61;
 svg.setAttribute('viewBox',`0 0 ${g.width} ${g.height}`);
 svg.querySelectorAll('path').forEach(p=>p.setAttribute('d',`M ${sx} ${sy} L ${x} ${y}`));
 svg.querySelectorAll('circle').forEach(c=>{c.setAttribute('cx',x);c.setAttribute('cy',y);});
 svg.dataset.target='supporting-ankle';svg.dataset.point=`${x.toFixed(2)},${y.toFixed(2)}`;
}
